import java.lang.reflect.Modifier;
import java.util.Arrays;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

public class Main {
    // --- sealed 接口：permits 列出所有直接子类型 ---
    sealed interface Expr permits Const, Add, Negate, ExtensionExpr {}

    record Const(int value) implements Expr {}          // final（record 隐式 final）
    record Add(Expr left, Expr right) implements Expr {} // final

    // --- sealed 子接口：下一层继续受控 ---
    sealed interface Negate extends Expr permits UnaryMinus {}
    record UnaryMinus(Expr inner) implements Negate {}   // final

    // --- non-sealed：从这个分支重新开放 ---
    non-sealed interface ExtensionExpr extends Expr {}
    static final class Variable implements ExtensionExpr {
        private final String name;
        Variable(String name) { this.name = name; }
        String name() { return name; }
    }

    // 模式匹配 + instanceof 分发（Java 16+）
    static int eval(Expr expr, Map<String, Integer> env) {
        if (expr instanceof Const c) return c.value();
        if (expr instanceof Add a) return eval(a.left(), env) + eval(a.right(), env);
        if (expr instanceof UnaryMinus n) return -eval(n.inner(), env);
        if (expr instanceof Variable v) return env.getOrDefault(v.name(), 0);
        throw new IllegalArgumentException("unsupported: " + expr.getClass().getName());
    }

    public static void main(String[] args) {
        // 基本算术表达式
        Expr expr = new Add(new Const(40), new UnaryMinus(new Add(new Const(1), new Const(2))));
        System.out.println("eval: " + eval(expr, Map.of()));          // 37

        // 包含扩展分支
        Expr ext = new Add(new Variable("x"), new Const(2));
        System.out.println("eval ext: " + eval(ext, Map.of("x", 5))); // 7

        // --- 运行时反射：观察 sealed 元数据 ---
        Set<String> permitted = Arrays.stream(Expr.class.getPermittedSubclasses())
            .map(Class::getSimpleName)
            .collect(Collectors.toSet());
        System.out.println("permitted: " + permitted);

        assert Expr.class.isSealed();
        assert permitted.equals(Set.of("Const", "Add", "Negate", "ExtensionExpr"));
        assert Modifier.isFinal(Const.class.getModifiers());      // record 隐式 final
        assert Negate.class.isSealed();                            // 下一层继续 sealed
        assert !ExtensionExpr.class.isSealed();                    // non-sealed，不再是 sealed
    }
}
